export const devices=[{id:'pendant',name:'Подвес',type:'Обеденная зона',icon:'⌒',watts:24},{id:'floor',name:'Торшер',type:'У дивана',icon:'♧',watts:8},{id:'accent',name:'Подсветка',type:'Мягкий контур',icon:'▱',watts:10}];
export const presets={morning:{scene:'morning',brightness:45,lights:{pendant:false,floor:false,accent:true},temperature:22,ac:true,day:true},evening:{scene:'evening',brightness:75,lights:{pendant:true,floor:true,accent:true},temperature:22,ac:true,day:false},cinema:{scene:'cinema',brightness:28,lights:{pendant:false,floor:false,accent:true},temperature:23,ac:true,day:false},away:{scene:'away',brightness:0,lights:{pendant:false,floor:false,accent:false},temperature:22,ac:false,day:false}};
export function preset(name){return JSON.parse(JSON.stringify(presets[name]||presets.evening))}
export function validate(input){const s=preset('evening');if(!input||typeof input!=='object')return s;if(Number.isFinite(input.brightness))s.brightness=Math.max(0,Math.min(100,input.brightness));if(Number.isFinite(input.temperature))s.temperature=Math.max(16,Math.min(30,Math.round(input.temperature)));for(const d of devices)if(typeof input.lights?.[d.id]==='boolean')s.lights[d.id]=input.lights[d.id];for(const k of ['ac','day'])if(typeof input[k]==='boolean')s[k]=input[k];s.scene=Object.hasOwn(presets,input.scene)?input.scene:'custom';return s}
export function estimatedWatts(s){return Math.round(devices.reduce((total,d)=>total+(s.lights[d.id]?d.watts:0),0)*s.brightness/100)}
